package com.loyu3c.rental;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.*;import java.util.zip.*;import javax.xml.parsers.*;
public class LedgerReportTest {
    private JSONObject backup()throws Exception{
        JSONArray expenses=new JSONArray();for(int i=0;i<40;i++)expenses.put(new JSONObject().put("id","e"+i).put("date",i==39?"2026-10-01":"2026-11-15").put("amount",100).put("category","repair").put("description",i==0?"=SUM(A1:A2) & <水電>\n第二行":"修繕 "+i).put("accountId","bank").put("void",i==38).put("voidReason","誤登").put("voidedAt","2026-11-15T00:00:00Z").put("splits",new JSONArray().put(new JSONObject().put("propertyId","p").put("amount",100))));
        return new JSONObject().put("expenses",expenses).put("incomes",new JSONArray().put(Income.create("2026-11-10","bank","利息收入","利息",25))).put("transfers",new JSONArray().put(new JSONObject().put("date","2026-11-10").put("amount",999999).put("fromId","bank").put("toId","cash"))).put("accounts",new JSONArray().put(new JSONObject().put("id","bank").put("name","農會"))).put("properties",new JSONArray().put(new JSONObject().put("id","p").put("name","1621"))).put("expenseCategories",new JSONArray().put(new JSONObject().put("id","repair").put("name","修繕")));
    }
    @Test public void reportIncludesUnloadedRowsAndExcludesVoidAndTransfers()throws Exception{JSONObject b=backup(),r=LedgerReport.build(b,"2026-11",0,"",false);assertEquals(39,r.getJSONArray("items").length());assertEquals(3800,r.getLong("expense"));assertEquals(25,r.getLong("income"));assertEquals(40,LedgerReport.select(b,"2026-11",0,"",false).size());assertEquals(40,b.getJSONArray("expenses").length());}
    @Test public void searchUsesAccountPropertyCategoryAndFormattedMoney()throws Exception{JSONObject b=backup();assertEquals(40,LedgerReport.select(b,"",0,"1621",false).size());assertEquals(41,LedgerReport.select(b,"",0,"農會",false).size());assertEquals(40,LedgerReport.select(b,"",0,"修繕",false).size());assertEquals(1,LedgerReport.select(b,"",0,"利息",false).size());}
    @Test public void voidRecordsRemainVisibleButNeverIncreaseTotals()throws Exception{JSONObject r=LedgerReport.build(backup(),"2026-11",2,"",true);assertEquals(1,r.getJSONArray("items").length());assertEquals(0,r.getLong("income"));assertEquals(0,r.getLong("expense"));assertEquals(0,LedgerReport.build(backup(),"",2,"",false).getJSONArray("items").length());}
    @Test public void workbookIsValidXmlWithNumericMoneyAndLiteralFormulaLikeText()throws Exception{JSONObject r=LedgerReport.build(backup(),"",0,"",true);ByteArrayOutputStream bytes=new ByteArrayOutputStream();LedgerReport.workbook(bytes,r);Map<String,String> entries=new HashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes.toByteArray()))){ZipEntry e;while((e=zip.getNextEntry())!=null){ByteArrayOutputStream xml=new ByteArrayOutputStream();zip.transferTo(xml);DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new ByteArrayInputStream(xml.toByteArray()));entries.put(e.getName(),xml.toString("UTF-8"));}}String rows=entries.get("xl/worksheets/sheet2.xml");assertTrue(rows.contains("=SUM(A1:A2) &amp; &lt;水電&gt;"));assertTrue(rows.contains("<v>100</v>"));assertFalse(rows.contains("<f>"));assertTrue(entries.get("xl/workbook.xml").contains("分攤明細"));assertTrue(entries.get("xl/worksheets/sheet3.xml").contains("1621"));assertTrue(rows.contains("已撤銷"));}
    @Test public void exportSnapshotIsIndependentFromLaterEdits()throws Exception{JSONObject b=backup(),r=LedgerReport.build(b,"",0,"",false);b.getJSONArray("expenses").getJSONObject(0).put("description","changed");assertFalse(r.getJSONArray("items").getJSONObject(0).getJSONObject("record").getString("description").equals("changed"));}
    @Test public void incomeExpenseTypeFilterIsSharedByExport()throws Exception{JSONObject b=backup();assertEquals(1,LedgerReport.select(b,"",0,"",false,1).size());assertEquals(40,LedgerReport.select(b,"",0,"",false,2).size());JSONObject r=LedgerReport.build(b,"",0,"",false,1);assertEquals(1,r.getJSONArray("items").length());assertEquals(25,r.getLong("income"));assertEquals(0,r.getLong("expense"));}

}
